import {
  IPageAction,
  PageActionSelection,
  PageActionType,
  useGetPageUrl,
  usePageAlertToaster,
} from '@ansible/ansible-ui-framework';
import { postRequest } from '@ansible/common-ui/crud/Data';
import { useOptions } from '@ansible/common-ui/crud/useOptions';
import { AlertProps, ButtonVariant } from '@patternfly/react-core';
import { MinusCircleIcon, PlusCircleIcon, RedoIcon, TrashIcon } from '@patternfly/react-icons';
import { useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { edaAPI, hasCopyNamePattern } from '../../common/eda-utils';
import { useEdaErrorMessageParser } from '../../common/edaErrorAdapter';
import { IEdaView } from '../../common/useEventDrivenView';
import { EdaRulebookActivation } from '../../interfaces/EdaRulebookActivation';
import { ActionsResponse, OptionsResponse } from '../../interfaces/OptionsResponse';
import { EdaRoute } from '../../main/EdaRoutes';
import {
  useDisableRulebookActivations,
  useDisableRulebookActivationsWithWarning,
  useEnableRulebookActivationsWithWarning,
  useRestartRulebookActivations,
  useRestartRulebookActivationsWithWarning,
} from './useControlRulebookActivations';
import {
  useDeleteRulebookActivations,
  useDeleteRulebookActivationsWithWarning,
} from './useDeleteRulebookActivations';
import { useClearLogs } from './useClearLogs';
import { StatusEnum } from '../../interfaces/generated/eda-api';

export function useRulebookActivationsActions(view: IEdaView<EdaRulebookActivation>) {
  const { t } = useTranslation();
  const deleteActivations = useDeleteRulebookActivations(view.unselectItemsAndRefresh);
  const deleteActivationsWithWarning = useDeleteRulebookActivationsWithWarning(
    view.unselectItemsAndRefresh
  );
  const disableActivations = useDisableRulebookActivations(view.unselectItemsAndRefresh);
  const disableActivationsWithWarning = useDisableRulebookActivationsWithWarning(
    view.unselectItemsAndRefresh
  );
  const restartActivations = useRestartRulebookActivations(view.unselectItemsAndRefresh);
  const parseError = useEdaErrorMessageParser();
  const { data } = useOptions<OptionsResponse<ActionsResponse>>(edaAPI`/activations/`);
  const canCreateActivations = Boolean(data && data.actions && data.actions['POST']);
  const alertToaster = usePageAlertToaster();
  const enableActivationsWithWarning = useEnableRulebookActivationsWithWarning(
    view.unselectItemsAndRefresh
  );
  const restartActivationsWithWarning = useRestartRulebookActivationsWithWarning(
    view.unselectItemsAndRefresh
  );
  const getPageUrl = useGetPageUrl();
  const clearLogs = useClearLogs();
  const enableRulebookActivation: (activation: EdaRulebookActivation) => Promise<void> =
    useCallback(
      async (activation) => {
        const alert: AlertProps = {
          variant: 'success',
          title: `${activation.name} ${t('enabled')}.`,
          timeout: 5000,
        };
        await postRequest(edaAPI`/activations/${activation.id.toString()}/enable/`, undefined)
          .then(() => alertToaster.addAlert(alert))
          .catch((err: Error) => {
            const errorResults = parseError(err);
            alertToaster.addAlert({
              variant: 'danger',
              title: `${t('Failed to enable')} ${activation.name}`,
              children: <>{errorResults.parsedErrors.map((errorResult) => errorResult.message)}</>,
              timeout: 5000,
            });
          });
      },
      [alertToaster, parseError, t]
    );
  const enableRulebookActivations = useCallback(
    async (activations: EdaRulebookActivation[]) => {
      if (activations.filter((activation) => hasCopyNamePattern(activation?.name)).length > 0) {
        enableActivationsWithWarning(activations);
      } else {
        const enablePromises = activations
          .filter((activation) => !activation.is_enabled)
          .map((activation) => enableRulebookActivation(activation));
        await Promise.allSettled(enablePromises);
        view.unselectItemsAndRefresh(activations);
      }
    },
    [enableActivationsWithWarning, enableRulebookActivation, view]
  );

  const restartRulebookActivations = useCallback(
    async (activations: EdaRulebookActivation[]) => {
      if (
        activations.filter((activation) => activation.status === StatusEnum.WorkersOffline).length >
        0
      ) {
        restartActivationsWithWarning(activations);
      } else {
        await restartActivations(activations);
      }
    },
    [restartActivations, restartActivationsWithWarning]
  );

  const disableRulebookActivations = useCallback(
    (activations: EdaRulebookActivation[]) => {
      if (activations.some((activation) => activation.status === StatusEnum.WorkersOffline)) {
        disableActivationsWithWarning(activations);
      } else {
        disableActivations(activations);
      }
    },
    [disableActivations, disableActivationsWithWarning]
  );

  const deleteRulebookActivations = useCallback(
    (activations: EdaRulebookActivation[]) => {
      if (activations.some((activation) => activation.status === StatusEnum.WorkersOffline)) {
        deleteActivationsWithWarning(activations);
      } else {
        deleteActivations(activations);
      }
    },
    [deleteActivations, deleteActivationsWithWarning]
  );

  return useMemo<IPageAction<EdaRulebookActivation>[]>(() => {
    const actions: IPageAction<EdaRulebookActivation>[] = [
      {
        type: PageActionType.Link,
        selection: PageActionSelection.None,
        variant: ButtonVariant.primary,
        isPinned: true,
        icon: PlusCircleIcon,
        label: t('Create rulebook activation'),
        isDisabled: canCreateActivations
          ? undefined
          : t(
              'You do not have permission to create a rulebook activation. Please contact your organization administrator if there is an issue with your access.'
            ),
        href: getPageUrl(EdaRoute.CreateRulebookActivation),
      },
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Multiple,
        icon: PlusCircleIcon,
        label: t('Enable rulebook activations'),
        onClick: (rulebookActivations: EdaRulebookActivation[]) =>
          enableRulebookActivations(rulebookActivations),
      },
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Multiple,
        icon: MinusCircleIcon,
        label: t('Disable rulebook activations'),
        onClick: (rulebookActivations: EdaRulebookActivation[]) =>
          disableRulebookActivations(rulebookActivations),
      },
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Multiple,
        icon: RedoIcon,
        label: t('Restart rulebook activations'),
        onClick: (rulebookActivations: EdaRulebookActivation[]) =>
          restartRulebookActivations(rulebookActivations),
      },
      {
        type: PageActionType.Seperator,
      },
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Multiple,
        icon: TrashIcon,
        label: t('Delete logs'),
        onClick: (activations: EdaRulebookActivation[]) =>
          clearLogs(
            activations.map((activation) => ({
              id: activation.id,
              name: activation.name,
              scope: 'activation',
            }))
          ),
        isDanger: true,
      },
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Multiple,
        icon: TrashIcon,
        label: t('Delete rulebook activations'),
        onClick: (rulebookActivations: EdaRulebookActivation[]) =>
          deleteRulebookActivations(rulebookActivations),
        isDanger: true,
      },
    ];
    return actions;
  }, [
    t,
    canCreateActivations,
    enableRulebookActivations,
    disableRulebookActivations,
    restartRulebookActivations,
    deleteRulebookActivations,
    getPageUrl,
    clearLogs,
  ]);
}
