import { PageTable, useDashboardColumns } from '@ansible/ansible-ui-framework';
import { PageDashboardCard } from '@ansible/ansible-ui-framework/PageDashboard/PageDashboardCard';
import { useGetPageUrl } from '@ansible/ansible-ui-framework/PageNavigation/useGetPageUrl';
import { PageTableEmptyState } from '@ansible/ansible-ui-framework/PageTable/PageTableEmptyState';
import { ButtonLink } from '@ansible/ansible-ui-framework/components/ButtonLink';
import { useOptions } from '@ansible/common-ui/crud/useOptions';
import { ButtonVariant } from '@patternfly/react-core';
import { PlusCircleIcon } from '@patternfly/react-icons';
import { useTranslation } from 'react-i18next';
import { awxAPI } from '../../common/api/awx-utils';
import { useAwxView } from '../../common/useAwxView';
import { Job } from '../../interfaces/Job';
import { ActionsResponse, OptionsResponse } from '../../interfaces/OptionsResponse';
import { AwxRoute } from '../../main/AwxRoutes';
import { useJobsColumns } from '../../views/jobs/hooks/useJobsColumns';
import { PageLoadingTable } from '@ansible/ansible-ui-framework/PageTable/PageLoadingTable';

export function AwxRecentJobsCard() {
  const getPageUrl = useGetPageUrl();
  const view = useAwxView<Job>({
    url: awxAPI`/unified_jobs/`,
    disableQueryString: true,
    defaultSort: 'finished',
    defaultSortDirection: 'desc',
  });
  const { t } = useTranslation();
  let columns = useJobsColumns();
  columns = useDashboardColumns(columns);

  const { data: jobTemplateActions, isLoading: isLoadingJobTemplateOptions } = useOptions<
    OptionsResponse<ActionsResponse>
  >(awxAPI`/job_templates/`);
  const { data: wfJobTemplateActions, isLoading: isLoadingWFJobTemplateOptions } = useOptions<
    OptionsResponse<ActionsResponse>
  >(awxAPI`/workflow_job_templates/`);
  const canCreateJobTemplate = Boolean(jobTemplateActions?.actions?.['POST']);
  const canCreateWFJobTemplate = Boolean(wfJobTemplateActions?.actions?.['POST']);

  if (isLoadingJobTemplateOptions || isLoadingWFJobTemplateOptions) {
    return (
      <PageDashboardCard>
        <PageLoadingTable rows={6} />
      </PageDashboardCard>
    );
  }

  return (
    <PageDashboardCard
      id="jobs-card"
      title={t('Jobs')}
      subtitle={t('Recently finished jobs')}
      width="md"
      height="md"
      linkText={t('View all Jobs')}
      to={getPageUrl(AwxRoute.Jobs)}
      disableBodyPadding
    >
      <PageTable<Job>
        disableBodyPadding={true}
        tableColumns={columns}
        autoHidePagination={true}
        errorStateTitle={t('Error loading jobs')}
        emptyState={
          canCreateJobTemplate || canCreateWFJobTemplate ? (
            <PageTableEmptyState
              title={t('There are currently no jobs')}
              description={t('Create a job by clicking the button below.')}
            >
              <ButtonLink
                icon={<PlusCircleIcon />}
                variant={ButtonVariant.primary}
                href={getPageUrl(AwxRoute.CreateJobTemplate)}
              >
                {t('Create job')}
              </ButtonLink>
            </PageTableEmptyState>
          ) : (
            <PageTableEmptyState
              icon={PlusCircleIcon}
              title={t('You do not have permission to create a job')}
              description={t(
                'Please contact your organization administrator if there is an issue with your access.'
              )}
            />
          )
        }
        {...view}
        compact
        itemCount={view.itemCount !== undefined ? Math.min(view.itemCount, 7) : undefined}
        pageItems={view.pageItems ? view.pageItems.slice(0, 7) : []}
        disableLastRowBorder
      />
    </PageDashboardCard>
  );
}
